A=[[8,8,6],[6,3,6],[6,8,8]]
out=[]
for tr in range(3):
  for rr in range(3):
    ri=rr if tr%2==0 else 2-rr
    row=[]
    for tc in range(3):
      for cc in range(3):
        ci=cc if tc%2==0 else 2-cc
        row.append(A[ri][ci])
    out.append(row)
print('\n'.join(' '.join(map(str,r)) for r in out))

